import{_ as o,l,o as e,c as s,v as t,p as n,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"ATT&CK","description":"","frontmatter":{"title":"ATT&CK","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mitre-attack.md","filePath":"cs/mitre-attack.md","lastUpdated":1789023840000}'),h={name:"cs/mitre-attack.md"};function T(m,a,_,A,u,E){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="att-ck" tabindex="-1">ATT&amp;CK <a class="header-anchor" href="#att-ck" aria-label="Permalink to &quot;ATT&amp;CK&quot;">​</a></h1><div class="epigraph"><p>ATT&amp;CK 把对手行为收成战术与技术矩阵，便于问检测覆盖而不是只问 CVE 列表。它是共同语言，不是自动等于你已被打穿。</p><footer>—— MITRE ATT&amp;CK；Strom 等对知识库的陈述</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/incident-response">事件响应</a>要分类。缺口是<strong>对手行为词典</strong>。本课讲矩阵怎么用于覆盖缺口，不把技术条目写成操作步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>工单只写恶意软件名，检测对不上。ATT&amp;CK：初始访问、执行、持久化等战术下挂技术。缺口是映射遥测：哪些技术我们根本看不见。</p><h3 id="不是清单作业" tabindex="-1">不是清单作业 <a class="header-anchor" href="#不是清单作业" aria-label="Permalink to &quot;不是清单作业&quot;">​</a></h3><p>覆盖 100% 技术既不可能也无意义。按威胁模型选。</p><p><span class="marginnote">MITRE。禁止按矩阵当攻击剧本。渗透测试下一课是授权下的检验。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选相关战术，对照日志源。下一课渗透测试方法论。</p>',12)),(e(),n(c,null,{default:r(()=>[p(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20TAC%5B%22%E6%88%98%E6%9C%AF%22%5D%20--%3E%20TECH%5B%22%E6%8A%80%E6%9C%AF%22%5D%0A%20%20TECH%20--%3E%20TEL%5B%22%E9%81%A5%E6%B5%8B%E6%9C%89%E6%97%A0%22%5D%0A%20%20TEL%20--%3E%20GAP%5B%22%E6%A3%80%E6%B5%8B%E7%BC%BA%E5%8F%A3%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>共同语言让蓝队与情报对接。渗透测试下一课用授权模拟来检验这些缺口。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不展开技术利用。渗透测试方法论下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>响应需要分类语言；ATT&amp;CK 给行为词典。</li><li>用来找检测缺口，不是打勾游戏。</li><li>按威胁模型选子集。</li><li>下一课渗透测试方法论。</li><li>出处：MITRE ATT&amp;CK。</li></ul>',8))])}const k=o(h,[["render",T]]);export{f as __pageData,k as default};
